import{b as t,O as e,g as s,j as n}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"附录C · Oracle 认证路线图","description":"","frontmatter":{},"headers":[],"relativePath":"database/oracle/appendix/certification/index.md","filePath":"数据库管理/Oracle从入门到精通/附录/C.认证路线图.md","lastUpdated":1782140566000}'),d={name:"database/oracle/appendix/certification/index.md"};function r(l,a,i,o,p,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="附录c-·-oracle-认证路线图" tabindex="-1">附录C · Oracle 认证路线图 <a class="header-anchor" href="#附录c-·-oracle-认证路线图" aria-label="Permalink to &quot;附录C · Oracle 认证路线图&quot;">​</a></h1><h2 id="认证体系概览" tabindex="-1">认证体系概览 <a class="header-anchor" href="#认证体系概览" aria-label="Permalink to &quot;认证体系概览&quot;">​</a></h2><p>Oracle 认证分为三个等级：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Oracle Certified Associate (OCA)    ← 助理级，入门</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Oracle Certified Professional (OCP) ← 专业级，含金量最高</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Oracle Certified Master (OCM)       ← 大师级，全球仅数千人</span></span></code></pre></div><h2 id="主要认证方向" tabindex="-1">主要认证方向 <a class="header-anchor" href="#主要认证方向" aria-label="Permalink to &quot;主要认证方向&quot;">​</a></h2><h3 id="_1-oracle-database-administration-数据库管理" tabindex="-1">1. Oracle Database Administration（数据库管理） <a class="header-anchor" href="#_1-oracle-database-administration-数据库管理" aria-label="Permalink to &quot;1. Oracle Database Administration（数据库管理）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级</th><th>考试</th><th>主要内容</th></tr></thead><tbody><tr><td>OCA</td><td>1Z0-082</td><td>SQL 基础、数据库管理基础</td></tr><tr><td>OCP</td><td>1Z0-083</td><td>RMAN、Data Pump、性能调优、RAC 基础</td></tr><tr><td>OCM</td><td>实操考试</td><td>两天动手实验，覆盖完整 DBA 技能</td></tr></tbody></table><h3 id="_2-oracle-sql-sql-专项" tabindex="-1">2. Oracle SQL（SQL 专项） <a class="header-anchor" href="#_2-oracle-sql-sql-专项" aria-label="Permalink to &quot;2. Oracle SQL（SQL 专项）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级</th><th>考试</th><th>主要内容</th></tr></thead><tbody><tr><td>OCA</td><td>1Z0-071</td><td>SQL 查询、DML/DDL、数据字典、多表连接</td></tr></tbody></table><blockquote><p>SQL 专项认证适合开发人员，不涉及 DBA 管理内容。</p></blockquote><h3 id="_3-oracle-pl-sql-developer-开发专项" tabindex="-1">3. Oracle PL/SQL Developer（开发专项） <a class="header-anchor" href="#_3-oracle-pl-sql-developer-开发专项" aria-label="Permalink to &quot;3. Oracle PL/SQL Developer（开发专项）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级</th><th>考试</th><th>主要内容</th></tr></thead><tbody><tr><td>OCA</td><td>1Z0-149</td><td>PL/SQL 编程、存储过程、函数、包、触发器</td></tr><tr><td>OCP</td><td>1Z0-148</td><td>高级 PL/SQL、性能调优、Oracle Application Express</td></tr></tbody></table><h2 id="学习路径建议" tabindex="-1">学习路径建议 <a class="header-anchor" href="#学习路径建议" aria-label="Permalink to &quot;学习路径建议&quot;">​</a></h2><h3 id="零基础-→-oca-dba" tabindex="-1">零基础 → OCA DBA <a class="header-anchor" href="#零基础-→-oca-dba" aria-label="Permalink to &quot;零基础 → OCA DBA&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1阶段：本教程 第1~3章    → 认识 Oracle、安装、体系结构基础</span></span>
<span class="line"><span>第2阶段：本教程 第4~8章    → SQL 实战（表、增删改、查询、函数、连接）</span></span>
<span class="line"><span>第3阶段：本教程 第9~14章   → 视图索引、PL/SQL、存储过程、备份恢复</span></span>
<span class="line"><span>第4阶段：本教程 第15~20章  → 深入体系结构、事务、锁、Redo/Undo</span></span>
<span class="line"><span>第5阶段：Oracle 官方教材   → 覆盖考试专属内容</span></span>
<span class="line"><span>第6阶段：模拟考试 + 真题   → 刷题巩固</span></span></code></pre></div><h3 id="oca-dba-→-ocp-dba" tabindex="-1">OCA DBA → OCP DBA <a class="header-anchor" href="#oca-dba-→-ocp-dba" aria-label="Permalink to &quot;OCA DBA → OCP DBA&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需要额外掌握：</span></span>
<span class="line"><span>  ├── RMAN 深度使用（增量备份、恢复目录、TSPITR）</span></span>
<span class="line"><span>  ├── Data Guard（主备同步、切换）</span></span>
<span class="line"><span>  ├── RAC 基础（集群概念、OCR、Voting Disk）</span></span>
<span class="line"><span>  ├── 性能调优深入（AWR 报告、ASH 报告、SQL Tuning Advisor）</span></span>
<span class="line"><span>  ├── 资源管理（Resource Manager）</span></span>
<span class="line"><span>  └── 多租户架构（CDB/PDB 管理）</span></span></code></pre></div><h2 id="备考建议" tabindex="-1">备考建议 <a class="header-anchor" href="#备考建议" aria-label="Permalink to &quot;备考建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>建议</th><th>说明</th></tr></thead><tbody><tr><td><strong>动手第一</strong></td><td>每学一个概念就上机验证，不要只背理论</td></tr><tr><td><strong>阅读官方文档</strong></td><td>Oracle Database Concepts + Administrator&#39;s Guide 是考试的基础</td></tr><tr><td><strong>做模拟题</strong></td><td>考试有大量场景题，熟悉题型比背知识点更重要</td></tr><tr><td><strong>关注版本</strong></td><td>考试基于特定版本（通常是 19c），不要学到 23ai 的新特性去考 19c</td></tr><tr><td><strong>OCP 需要培训</strong></td><td>OCP 考试要求完成 Oracle 官方认可的培训课程（或在线培训）</td></tr></tbody></table><h2 id="考试信息" tabindex="-1">考试信息 <a class="header-anchor" href="#考试信息" aria-label="Permalink to &quot;考试信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>考试形式</td><td>选择题（单选 + 多选）</td></tr><tr><td>题目数量</td><td>约 60~85 题</td></tr><tr><td>考试时间</td><td>120~150 分钟</td></tr><tr><td>通过分数</td><td>约 60%~65%</td></tr><tr><td>考试平台</td><td>Pearson VUE（线上或考场）</td></tr><tr><td>费用</td><td>OCA $150~250，OCP $250~400（不含培训）</td></tr><tr><td>证书有效期</td><td>永久有效（部分新政策可能有变，以官网为准）</td></tr></tbody></table>`,21)])])}const u=t(d,[["render",r]]);export{b as __pageData,u as default};
